import {
  Component,
  Element,
  Event,
  type EventEmitter,
  Host,
  Method,
  Prop,
  State,
  Watch,
  h,
} from "@stencil/core";
import { arrowLeft, arrowRight } from "../../../icons";
import { focusVisible } from "../../utils/focus-visible";
import getBootstrapConfig from "../../utils/getBootstrapConfig";
import { scrollIntoView } from "../../utils/scroll";

/**
 * @since 0.0.15
 * @status experimental
 *
 * @data-testid scroll-left-button - The previous-tab scroll control shown when the tab list overflows.
 * @data-testid scroll-right-button - The next-tab scroll control shown when the tab list overflows.
 *
 * @slot nav - Used for grouping tabs in the tab group.
 * @slot - Used for grouping tab panels in the tab group.
 *
 * @part base - The component's base wrapper.
 * @part nav-container - The tab group navigation container
 * @part nav - The tab group navigation bar
 * @part tabs - The container that wraps the slotted tabs.
 * @part active-tab-indicator - An element that displays the currently selected tab. This is a child of the tabs container.
 * @part body - The tab group body where tab panels are slotted in.
 * @part scroll-button - The previous and next scroll buttons that appear when tabs are scrollable.
 */

@Component({
  tag: "hbr-tab-group",
  styleUrl: "tab-group.scss",
  shadow: true,
})
export class TabGroup {
  sheet: CSSStyleSheet = new CSSStyleSheet();
  activeTab: HTMLHbrTabElement;
  activeTabIndicator: HTMLElement;
  body: HTMLElement;
  mutationObserver: MutationObserver;
  nav: HTMLElement;
  resizeObserver: ResizeObserver;
  tabGroup: HTMLElement;
  tabs: HTMLElement;

  @Element() host: HTMLHbrTabGroupElement;

  @State() hasScrollControls = false;
  @State() isScrolledToLeft = false;
  @State() isScrolledToRight = false;

  /** The placement of the tabs. */
  @Prop() placement: "top" | "bottom" | "left" | "right" = "top";

  /** Disables the scroll arrows that appear when tabs overflow. */
  @Prop() noScrollControls = false;

  /** Disables hbr-active event bubbling up  */
  @Prop() noActiveEventBubble = true;

  /** Disables hbr-select event bubbling up  */
  @Prop() noSelectEventBubble = true;

  /** Set to true to control the tab group's state from the application / framework's side */
  @Prop() uncontrolled = false;

  /** Set to true to enable to use css gap instead of the margin. version:2.9.12 */
  @Prop({ reflect: true }) gap = false;

  @Prop({ reflect: true }) size: "small" | "medium" | "large" = "medium";

  @Prop({ mutable: true, reflect: true }) sentiment = "interact";

  @Prop({ mutable: true, reflect: true }) primary = false;

  @Watch("noScrollControls")
  handleNoScrollControlsChange() {
    this.updateScrollControls();
  }

  /** Emitted when a tab is shown. */
  @Event({ eventName: "hbr-tab-show" }) hbrTabShow: EventEmitter<{
    name: string;
  }>;

  /** Emitted when a tab is hidden. */
  @Event({ eventName: "hbr-tab-hide" }) hbrTabHide: EventEmitter<{
    name: string;
  }>;

  connectedCallback() {
    this.handleClick = this.handleClick.bind(this);
    this.handleKeyDown = this.handleKeyDown.bind(this);
    this.handleScrollLeft = this.handleScrollLeft.bind(this);
    this.handleScrollRight = this.handleScrollRight.bind(this);
    this.stopBubbleHbrActiveEvent = this.stopBubbleHbrActiveEvent.bind(this);
    this.listenActiveTab = this.listenActiveTab.bind(this);
    this.setNestedActiveTab = this.setNestedActiveTab.bind(this);
    this.updateScrollControls = this.updateScrollControls.bind(this);
  }

  componentDidLoad() {
    // Set initial tab state when the tabs first become visible
    let load = false;
    const observer = new IntersectionObserver((entries, observer) => {
      if (entries[0].intersectionRatio > 0) {
        this.setAriaLabels();
        if (!this.uncontrolled) {
          this.setActiveTab(this.getActiveTab() || this.getAllTabs()[0], false);
        }
        load = true;
        observer.unobserve(entries[0].target);
      }
    });
    setTimeout(() => {
      // IntersectionObserver call is not guaranteed
      if (load === false) {
        this.setAriaLabels();
        if (!this.uncontrolled) {
          this.setActiveTab(this.getActiveTab() || this.getAllTabs()[0], false);
        }
      }
    }, 500);
    observer.observe(this.host);

    focusVisible.observe(this.tabGroup);

    this.resizeObserver = new ResizeObserver(this.updateScrollControls);
    this.resizeObserver.observe(this.nav);
    requestAnimationFrame(this.updateScrollControls);

    // Update aria labels if the DOM changes
    this.mutationObserver = new MutationObserver((mutations) => {
      if (
        mutations.some((mutation) => {
          return !["aria-labelledby", "aria-controls"].includes(
            mutation.attributeName
          );
        })
      ) {
        setTimeout(() => this.setAriaLabels());
      }
    });
    this.mutationObserver.observe(this.host, {
      attributes: true,
      childList: true,
      subtree: true,
    });
  }

  disconnectedCallback() {
    this.mutationObserver?.disconnect();
    focusVisible?.unobserve(this.tabGroup);
    this.resizeObserver?.unobserve(this.nav);
  }

  /** Shows the specified tab panel. */
  @Method()
  async show(panel: string) {
    const tabs = this.getAllTabs();
    const tab = tabs.find((el) => el.panel === panel);

    if (tab) {
      this.setActiveTab(tab);
    }
  }

  getTab = (ele, includeButton) => {
    if (includeButton) {
      return (
        (ele.tagName === "HBR-TAB" && !ele.nested) ||
        (ele.tagName === "HBR-BUTTON" && ele.ariarole === "tab")
      );
    }
    return ele.tagName === "HBR-TAB";
  };

  getAllTabs(includeDisabled = false, includeButton = false) {
    const slot = this.tabs.querySelector("slot");
    const list = [...slot.assignedElements({ flatten: true })];
    if (includeButton) {
      const buttonList = [];
      list.forEach((e: HTMLHbrTabElement) => {
        if (e.nested) {
          const button = e?.querySelector(
            "hbr-button[ariarole='tab']"
          ) as HTMLHbrButtonElement;
          if (button) {
            if (includeDisabled) {
              button && buttonList.push(button);
            } else {
              button && !button.disabled && buttonList.push(button);
            }
          }
        }
      });
      list.push(...buttonList);
    }

    return list.filter((el: HTMLHbrTabElement) => {
      return includeDisabled
        ? this.getTab(el, includeButton)
        : this.getTab(el, includeButton) && !el.disabled;
    }) as [HTMLHbrTabElement];
  }

  getAllPanels() {
    const slot = this.body.querySelector("slot");
    return [...slot.assignedElements()].filter(
      (el: HTMLElement) => el.tagName.toLowerCase() === "hbr-tab-panel"
    ) as [HTMLHbrTabPanelElement];
  }

  getActiveTab() {
    return this.getAllTabs().find((el) => el.active);
  }

  handleClick(event: MouseEvent) {
    if (this.uncontrolled) return;
    const target = event.target as HTMLElement;
    const tab = target.closest("hbr-tab");
    const tabGroup = tab?.closest("hbr-tab-group");

    // Ensure the target tab is in this tab group
    if (tabGroup !== this.host) {
      return false;
    }

    if (tab) {
      if (this.uncontrolled) return;
      const dropdown = this.host.querySelector(
        "hbr-dropdown"
      ) as HTMLHbrDropdownElement;
      if (dropdown) {
        dropdown.value = "";
      }
      this.setActiveTab(tab);
    }
  }

  handleKeyDown(event: KeyboardEvent) {
    const target = event.target as HTMLElement;
    const tab = target.closest("hbr-tab");
    const tabGroup = tab?.closest("hbr-tab-group");

    // Ensure the target tab is in this tab group
    if (tabGroup !== this.host) {
      return false;
    }

    // Activate a tab
    if (["Enter", " "].includes(event.key)) {
      if (tab) {
        if (this.uncontrolled) return;
        const dropdown = this.host.querySelector(
          "hbr-dropdown"
        ) as HTMLHbrDropdownElement;
        if (dropdown) {
          dropdown.value = "";
        }
        if (target.tagName !== "HBR-BUTTON") {
          this.setActiveTab(tab);
        }
        event.preventDefault();
      }
    }

    // Move focus left or right
    if (
      [
        "ArrowLeft",
        "ArrowRight",
        "ArrowUp",
        "ArrowDown",
        "Home",
        "End",
      ].includes(event.key)
    ) {
      let activeEl = document.activeElement as HTMLHbrTabElement;
      if (!["HBR-TAB", "HBR-BUTTON"].includes(activeEl.tagName)) {
        activeEl = activeEl.closest("hbr-tab");
      }

      if (activeEl && ["HBR-TAB", "HBR-BUTTON"].includes(activeEl.tagName)) {
        const tabs = this.getAllTabs(false, true);
        let index = tabs.indexOf(activeEl);

        if (event.key === "Home") {
          index = 0;
        } else if (event.key === "End") {
          index = tabs.length - 1;
        } else if (event.key === "ArrowLeft") {
          index = Math.max(0, index - 1);
        } else if (event.key === "ArrowRight") {
          index = Math.min(tabs.length - 1, index + 1);
        }

        tabs[index]?.setFocus({ preventScroll: true });

        if (["top", "bottom"].includes(this.placement)) {
          // ts-ignore
          tabs[index] && scrollIntoView(tabs[index], this.nav, "horizontal");
        }
      }
    }
  }

  handleScrollLeft() {
    this.nav.scroll({
      left: this.nav.scrollLeft - this.nav.clientWidth,
      behavior: "smooth",
    });
    this.handleScroll();
  }

  handleScrollRight() {
    this.nav.scroll({
      left: this.nav.scrollLeft + this.nav.clientWidth,
      behavior: "smooth",
    });
    this.handleScroll();
  }

  handleScroll = () => {
    const nav = this.nav;
    if (nav) {
      this.isScrolledToLeft = nav.scrollLeft === 0;
      this.isScrolledToRight =
        Math.ceil(nav.scrollLeft + nav.clientWidth) >= nav.scrollWidth;
    }
  };

  updateScrollControls() {
    if (this.noScrollControls) {
      this.hasScrollControls = false;
    } else {
      this.hasScrollControls =
        ["top", "bottom"].includes(this.placement) &&
        this.nav.scrollWidth - 1 > this.nav.clientWidth;
      // the -1 solution is for the weird bug in safari #978
      // disabled the left and right scroll buttons
      this.handleScroll();
    }
  }

  setActiveTab(tab: HTMLHbrTabElement, emitEvents = true, isNested = false) {
    const isNestedTab = tab?.closest("hbr-tab-panel");
    if (isNestedTab && this.host.contains(isNestedTab)) return;
    const isTabVertical = tab?.closest("hbr-tab-vertical");
    if (isTabVertical && this.host.contains(isTabVertical)) return;
    if (
      (tab && tab !== this.activeTab && !tab.disabled) ||
      (isNested && tab && !tab.disabled)
    ) {
      const previousTab = this.activeTab;
      this.activeTab = tab;

      // Sync tabs and panels
      this.getAllTabs().map((el) => {
        el.active = el === this.activeTab;
      });
      this.getAllPanels().map((el) => {
        el.active = el.name === this.activeTab.panel;
      });

      if (["top", "bottom"].includes(this.placement)) {
        // ts-ignore
        scrollIntoView(this.activeTab, this.nav, "horizontal");
      }

      // Emit events
      if (emitEvents) {
        if (previousTab) {
          this.hbrTabHide.emit({ name: previousTab.panel });
        }

        this.hbrTabShow.emit({ name: this.activeTab.panel });
      }
    }
  }

  setAriaLabels() {
    const tabs = this.getAllTabs();
    const panels = this.getAllPanels();

    // Link each tab with its corresponding panel
    tabs.map((tab) => {
      const panel = panels.find((el) => el.name === tab.panel);
      if (panel) {
        tab.setAttribute("aria-controls", panel.getAttribute("id"));
        panel.setAttribute("aria-labelledby", tab.getAttribute("id"));
      }
    });
  }

  listenActiveTab(event: CustomEvent) {
    const tab = event?.detail?.tab;
    tab && this.setActiveTab(tab);
  }

  setNestedActiveTab(e) {
    const tab = e?.target?.closest("hbr-tab");
    if (tab?.nested) {
      const panel = e?.detail?.item?.getAttribute("panel");
      if (tab && panel) {
        tab.panel = panel;
        this.setActiveTab(tab, true, true);
      }
    }
  }

  stopBubbleHbrActiveEvent(event: CustomEvent) {
    this.noActiveEventBubble && event.stopPropagation();
  }

  stopBubbleHbrSelectEvent(event: CustomEvent) {
    this.noSelectEventBubble && event.stopPropagation();
  }

  render() {
    const customSystemIcons = getBootstrapConfig()?.systemIcons;
    return (
      <Host
        onHbr-active={this.stopBubbleHbrActiveEvent}
        onHbr-select={this.stopBubbleHbrSelectEvent}
      >
        <div
          part="base"
          ref={(el) => {
            this.tabGroup = el;
          }}
          class={{
            "tab-group": true,

            // Placements
            "tab-group--top": this.placement === "top",
            "tab-group--bottom": this.placement === "bottom",
            "tab-group--left": this.placement === "left",
            "tab-group--right": this.placement === "right",

            "tab-group--has-scroll-controls": this.hasScrollControls,
            "tab-group--large": this.size === "large",
            "tab-group--medium": this.size === "medium",
            "tab-group--small": this.size === "small",
            "tab-group--primary": this.primary,
          }}
          onClick={this.handleClick}
          onKeyDown={this.handleKeyDown}
          onHbr-active={this.listenActiveTab}
          onHbr-select={this.setNestedActiveTab}
        >
          <div class="tab-group__nav-container" part="nav-container">
            {this.hasScrollControls && (
              <hbr-icon-button
                arialabel="previous"
                class="tab-group__scroll-button tab-group__scroll-button--left"
                exportparts="base:scroll-button, base:scroll-button-left"
                disabled={this.isScrolledToLeft}
                asset={customSystemIcons?.["arrow-left"] || arrowLeft}
                data-testid="scroll-left-button"
                onClick={this.handleScrollLeft}
              />
            )}
            <div
              ref={(el) => {
                this.nav = el;
              }}
              key="nav"
              part="nav"
              class={{
                "tab-group__nav": true,
                "tab-group__nav-scroll": this.hasScrollControls,
              }}
              onScroll={this.handleScroll}
            >
              <div
                ref={(el) => {
                  this.tabs = el;
                }}
                part="tabs"
                class={{
                  "tab-group__tabs": true,
                  "tab-group__tabs-gap": this.gap,
                }}
                role="tablist"
                aria-orientation="horizontal"
              >
                <slot name="nav" />
              </div>
            </div>
            {this.hasScrollControls && (
              <hbr-icon-button
                arialabel="next"
                class="tab-group__scroll-button tab-group__scroll-button--right"
                exportparts="base:scroll-button, base:scroll-button-right"
                disabled={this.isScrolledToRight}
                asset={customSystemIcons?.["arrow-right"] || arrowRight}
                data-testid="scroll-right-button"
                onClick={this.handleScrollRight}
              />
            )}
          </div>

          <div
            ref={(el) => {
              this.body = el;
            }}
            part="body"
            class="tab-group__body"
          >
            <slot />
          </div>
        </div>
      </Host>
    );
  }
}
